-- 세트 232: 사용자와 그룹 손에 익히기: id, useradd, usermod -aG, chown, chmod g+w, su -c
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_linux_users_groups_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (232, 1, '사용자 kim 의 신원 확인하기 (id)', '이 서버에는 `kim` 이라는 사용자가 있습니다. 권한 문제를 볼 때 가장 먼저 확인하는 것은 "이 사용자가 누구고 어느 그룹에 속해 있나" 입니다. `kim` 의 **UID, 기본 그룹, 속한 모든 그룹**이 한눈에 나오는 명령의 결과를 `/tmp/kim_id.txt` 에 저장하세요.', '`id 사용자이름` 은 UID, GID, 보조 그룹을 한 줄로 보여 줍니다. 결과는 `>` 로 파일에 보내세요.', 'id kim > /tmp/kim_id.txt
cat /tmp/kim_id.txt

# uid=사용자번호(이름) gid=기본그룹번호(이름) groups=속한 모든 그룹. groups 만 이름으로 보려면 id -nG kim', '["sh", "-c", "for u in kim lee park guest; do userdel -r $u 2>/dev/null; done\\nrm -rf /data/lee /srv/team; mkdir -p /data\\nfor g in devs audit ops team kim lee park guest; do groupdel $g 2>/dev/null; done\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\ngroupadd devs; groupadd audit\\nuseradd -m -s /bin/bash kim\\nuseradd -m -d /data/lee -s /bin/bash lee\\nuseradd -m -s /bin/bash guest\\nusermod -aG devs kim; usermod -aG devs lee; usermod -aG audit lee\\necho \\"draft report\\" > /tmp/lab/report.txt\\necho \\"team notes\\" > /tmp/lab/team.txt; chown kim:devs /tmp/lab/team.txt; chmod 644 /tmp/lab/team.txt\\necho hello > /home/guest/note.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/kim_id.txt)\\" = \\"$(id kim)\\" ] ) && ( grep -q \\"uid=$(id -u kim)(kim)\\" /tmp/kim_id.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 id kim 의 출력과 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/kim_id.txt)\\" = \\"$(id kim)\\" ]"]}, {"label": "kim 의 UID 가 들어 있다", "cmd": ["sh", "-c", "grep -q \\"uid=$(id -u kim)(kim)\\" /tmp/kim_id.txt"]}]', '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 2, '/etc/passwd 에서 홈 디렉터리 필드 뽑기', '사용자 정보는 `/etc/passwd` 에 `이름:x:UID:GID:설명:홈디렉터리:로그인셸` 처럼 **콜론(:)으로 나뉜 7칸**으로 저장됩니다. `lee` 의 **홈 디렉터리 경로만** `/tmp/lee_home.txt` 에 저장하세요. (한 줄)', '`grep ^lee: /etc/passwd` 로 한 줄을 뽑고, `cut -d: -f번호` 로 원하는 칸만 자를 수 있습니다. 홈 디렉터리는 몇 번째 칸일까요? 흔한 `/home/lee` 가 아닐 수도 있으니 직접 읽어서 적지 말고 명령 결과를 파일로 보내세요.', 'grep ''^lee:'' /etc/passwd | cut -d: -f6 > /tmp/lee_home.txt
cat /tmp/lee_home.txt

# 칸 번호: 1 이름, 2 비밀번호(x), 3 UID, 4 GID, 5 설명, 6 홈 디렉터리, 7 로그인 셸. getent passwd lee 도 같은 한 줄을 준다', '["sh", "-c", "for u in kim lee park guest; do userdel -r $u 2>/dev/null; done\\nrm -rf /data/lee /srv/team; mkdir -p /data\\nfor g in devs audit ops team kim lee park guest; do groupdel $g 2>/dev/null; done\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\ngroupadd devs; groupadd audit\\nuseradd -m -s /bin/bash kim\\nuseradd -m -d /data/lee -s /bin/bash lee\\nuseradd -m -s /bin/bash guest\\nusermod -aG devs kim; usermod -aG devs lee; usermod -aG audit lee\\necho \\"draft report\\" > /tmp/lab/report.txt\\necho \\"team notes\\" > /tmp/lab/team.txt; chown kim:devs /tmp/lab/team.txt; chmod 644 /tmp/lab/team.txt\\necho hello > /home/guest/note.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/lee_home.txt)\\" -eq 1 ] && grep -q \\"^/\\" /tmp/lee_home.txt ) && ( [ \\"$(cat /tmp/lee_home.txt)\\" = \\"$(getent passwd lee | cut -d: -f6)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "한 줄이고 / 로 시작한다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lee_home.txt)\\" -eq 1 ] && grep -q \\"^/\\" /tmp/lee_home.txt"]}, {"label": "lee 의 실제 홈 디렉터리와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/lee_home.txt)\\" = \\"$(getent passwd lee | cut -d: -f6)\\" ]"]}]', '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 3, 'bash 를 쓰는 계정 이름만 모으기 (awk -F:)', '모든 계정이 로그인할 수 있는 것은 아닙니다. 시스템 계정은 `/usr/sbin/nologin` 같은 셸을 가집니다. 로그인 셸이 **`/bin/bash`** 인 계정의 **이름만** 한 줄에 하나씩 `/tmp/bash_users.txt` 에 저장하세요.', '`awk -F: ...` 의 `-F:` 는 칸 구분자를 콜론으로 정합니다. 로그인 셸은 7번째 칸이라 `$7` 입니다. `awk -F: ''$7=="값" {print $1}''` 꼴로 조건과 출력을 쓰세요.', 'awk -F: ''$7=="/bin/bash" {print $1}'' /etc/passwd > /tmp/bash_users.txt
cat /tmp/bash_users.txt

# awk 는 조건 {동작} 형태. 7번째 칸이 /bin/bash 인 줄만 골라 1번째 칸(이름)을 출력한다', '["sh", "-c", "for u in kim lee park guest; do userdel -r $u 2>/dev/null; done\\nrm -rf /data/lee /srv/team; mkdir -p /data\\nfor g in devs audit ops team kim lee park guest; do groupdel $g 2>/dev/null; done\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\ngroupadd devs; groupadd audit\\nuseradd -m -s /bin/bash kim\\nuseradd -m -d /data/lee -s /bin/bash lee\\nuseradd -m -s /bin/bash guest\\nusermod -aG devs kim; usermod -aG devs lee; usermod -aG audit lee\\necho \\"draft report\\" > /tmp/lab/report.txt\\necho \\"team notes\\" > /tmp/lab/team.txt; chown kim:devs /tmp/lab/team.txt; chmod 644 /tmp/lab/team.txt\\necho hello > /home/guest/note.txt\\ntrue"]', '["sh", "-c", "( grep -qx kim /tmp/bash_users.txt && grep -qx lee /tmp/bash_users.txt ) && ( ! grep -qx haproxy /tmp/bash_users.txt ) && ( [ \\"$(sort /tmp/bash_users.txt)\\" = \\"$(awk -F: ''$7==\\"/bin/bash\\"{print $1}'' /etc/passwd | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "kim 과 lee 가 들어 있다", "cmd": ["sh", "-c", "grep -qx kim /tmp/bash_users.txt && grep -qx lee /tmp/bash_users.txt"]}, {"label": "nologin 계정은 없다", "cmd": ["sh", "-c", "! grep -qx haproxy /tmp/bash_users.txt"]}, {"label": "/bin/bash 계정 목록과 정확히 같다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/bash_users.txt)\\" = \\"$(awk -F: ''$7==\\"/bin/bash\\"{print $1}'' /etc/passwd | sort)\\" ]"]}]', '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 4, '새 계정 만들기 (useradd -m -s)', '새 팀원 `park` 의 계정을 만드세요. **홈 디렉터리가 함께 만들어지고, 로그인 셸은 `/bin/bash`** 여야 합니다.', '`useradd` 는 옵션을 안 주면 홈 디렉터리를 만들지 않을 수 있고, 셸도 기본값(`/bin/sh`)이 됩니다. 홈 디렉터리를 만드는 옵션과 셸을 정하는 옵션을 찾아보세요. `useradd --help` 가 도움이 됩니다.', 'useradd -m -s /bin/bash park
getent passwd park
ls -ld /home/park

# -m 홈 디렉터리 생성(/etc/skel 의 기본 파일 복사), -s 로그인 셸 지정. 확인은 getent passwd park', '["sh", "-c", "for u in kim lee park guest; do userdel -r $u 2>/dev/null; done\\nrm -rf /data/lee /srv/team; mkdir -p /data\\nfor g in devs audit ops team kim lee park guest; do groupdel $g 2>/dev/null; done\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\ngroupadd devs; groupadd audit\\nuseradd -m -s /bin/bash kim\\nuseradd -m -d /data/lee -s /bin/bash lee\\nuseradd -m -s /bin/bash guest\\nusermod -aG devs kim; usermod -aG devs lee; usermod -aG audit lee\\necho \\"draft report\\" > /tmp/lab/report.txt\\necho \\"team notes\\" > /tmp/lab/team.txt; chown kim:devs /tmp/lab/team.txt; chmod 644 /tmp/lab/team.txt\\necho hello > /home/guest/note.txt\\ntrue"]', '["sh", "-c", "( getent passwd park > /dev/null ) && ( [ \\"$(getent passwd park | cut -d: -f7)\\" = /bin/bash ] ) && ( [ -d /home/park ] && [ \\"$(stat -c %U /home/park)\\" = park ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "park 계정이 있다", "cmd": ["sh", "-c", "getent passwd park > /dev/null"]}, {"label": "로그인 셸이 /bin/bash 다", "cmd": ["sh", "-c", "[ \\"$(getent passwd park | cut -d: -f7)\\" = /bin/bash ]"]}, {"label": "홈 디렉터리가 있고 park 소유다", "cmd": ["sh", "-c", "[ -d /home/park ] && [ \\"$(stat -c %U /home/park)\\" = park ]"]}]', '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 5, '기존 그룹에 사용자 더하기 (usermod -aG)', '`kim` 을 `audit` 그룹에도 넣어 주세요. 단, `kim` 이 이미 속한 **기존 그룹은 그대로 유지**되어야 합니다. 기본 그룹도 바뀌면 안 됩니다.', '`usermod` 로 보조 그룹을 정하는 옵션은 `-G` 입니다. 그냥 `-G` 만 쓰면 목록이 통째로 **교체**됩니다. 기존 목록에 덧붙이는 옵션을 같이 쓰세요. 결과는 `id -nG kim` 으로 확인합니다.', 'id -nG kim
usermod -aG audit kim
id -nG kim

# -a(append) 없이 -G audit 만 쓰면 devs 가 빠진다. 반드시 -aG 한 쌍으로', '["sh", "-c", "for u in kim lee park guest; do userdel -r $u 2>/dev/null; done\\nrm -rf /data/lee /srv/team; mkdir -p /data\\nfor g in devs audit ops team kim lee park guest; do groupdel $g 2>/dev/null; done\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\ngroupadd devs; groupadd audit\\nuseradd -m -s /bin/bash kim\\nuseradd -m -d /data/lee -s /bin/bash lee\\nuseradd -m -s /bin/bash guest\\nusermod -aG devs kim; usermod -aG devs lee; usermod -aG audit lee\\necho \\"draft report\\" > /tmp/lab/report.txt\\necho \\"team notes\\" > /tmp/lab/team.txt; chown kim:devs /tmp/lab/team.txt; chmod 644 /tmp/lab/team.txt\\necho hello > /home/guest/note.txt\\ntrue"]', '["sh", "-c", "( id -nG kim | tr \\" \\" \\"\\\\n\\" | grep -qx audit ) && ( id -nG kim | tr \\" \\" \\"\\\\n\\" | grep -qx devs ) && ( [ \\"$(id -gn kim)\\" = kim ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "kim 이 audit 그룹에 있다", "cmd": ["sh", "-c", "id -nG kim | tr \\" \\" \\"\\\\n\\" | grep -qx audit"]}, {"label": "kim 이 devs 그룹에 그대로 있다", "cmd": ["sh", "-c", "id -nG kim | tr \\" \\" \\"\\\\n\\" | grep -qx devs"]}, {"label": "기본 그룹은 kim 이다", "cmd": ["sh", "-c", "[ \\"$(id -gn kim)\\" = kim ]"]}]', '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 6, '계정 잠그기', '퇴사한 팀원의 계정 `guest` 로 **비밀번호 로그인을 못 하게 잠그려고** 합니다. 빈칸에 알맞은 옵션을 채우세요.', '`passwd` 옵션은 계정을 잠그기, 잠금 풀기, 상태 보기, 비밀번호 만료시키기처럼 목적이 각각 다릅니다. `passwd --help` 로 설명을 읽어 보세요.', NULL, NULL, '[]', 'fill', '["-l", "-u", "-S", "-e"]', NULL, '`passwd -l`(lock)은 비밀번호 앞에 `!` 를 붙여 비밀번호 로그인을 막습니다. `-u` 는 잠금을 풀고, `-S` 는 상태만 보여 주며, `-e` 는 다음 로그인 때 비밀번호를 바꾸게 만들 뿐 잠그지는 않습니다.', '[0]', 'passwd {0} guest', NULL, '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 7, '파일 소유자와 그룹 한 번에 바꾸기 (chown 사용자:그룹)', '`/tmp/lab/report.txt` 는 지금 root 소유입니다. 소유자를 **`kim`**, 그룹을 **`devs`** 로 한 번에 바꾸세요. 파일 내용은 그대로 둡니다.', '`ls -l` 로 현재 소유자와 그룹을 먼저 보세요. `chown` 은 `사용자:그룹` 형태로 두 값을 한꺼번에 받을 수 있습니다.', 'ls -l /tmp/lab/report.txt
chown kim:devs /tmp/lab/report.txt
ls -l /tmp/lab/report.txt

# chown 사용자 파일 / chown :그룹 파일 / chown 사용자:그룹 파일. 폴더 전체는 -R', '["sh", "-c", "for u in kim lee park guest; do userdel -r $u 2>/dev/null; done\\nrm -rf /data/lee /srv/team; mkdir -p /data\\nfor g in devs audit ops team kim lee park guest; do groupdel $g 2>/dev/null; done\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\ngroupadd devs; groupadd audit\\nuseradd -m -s /bin/bash kim\\nuseradd -m -d /data/lee -s /bin/bash lee\\nuseradd -m -s /bin/bash guest\\nusermod -aG devs kim; usermod -aG devs lee; usermod -aG audit lee\\necho \\"draft report\\" > /tmp/lab/report.txt\\necho \\"team notes\\" > /tmp/lab/team.txt; chown kim:devs /tmp/lab/team.txt; chmod 644 /tmp/lab/team.txt\\necho hello > /home/guest/note.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(stat -c %U:%G /tmp/lab/report.txt)\\" = kim:devs ] ) && ( grep -q \\"draft report\\" /tmp/lab/report.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "소유자와 그룹이 kim:devs 다", "cmd": ["sh", "-c", "[ \\"$(stat -c %U:%G /tmp/lab/report.txt)\\" = kim:devs ]"]}, {"label": "내용은 그대로다", "cmd": ["sh", "-c", "grep -q \\"draft report\\" /tmp/lab/report.txt"]}]', '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 8, '그룹 쓰기 권한 열어 주기 (chmod g+w)', '`/tmp/lab/team.txt` 는 `kim`(소유자)과 `devs` 그룹 파일인데, 지금은 소유자만 쓸 수 있습니다. `lee` 도 `devs` 그룹이니 **그룹에게 쓰기 권한만 추가**해 `lee` 가 이 파일을 쓸 수 있게 하세요. 다른 사용자(others)에게는 쓰기를 주면 안 됩니다.', '`ls -l` 의 권한 문자열은 소유자·그룹·others 순서로 세 칸씩입니다. `chmod` 의 기호 모드에서 `g` 는 그룹, `+w` 는 쓰기 추가를 뜻합니다. 숫자 666 처럼 한꺼번에 열면 others 도 열려 버려요.', 'ls -l /tmp/lab/team.txt
chmod g+w /tmp/lab/team.txt
ls -l /tmp/lab/team.txt

# -rw-r--r-- 에서 -rw-rw-r-- 로. 대상(u/g/o) + 연산(+/-) + 권한(r/w/x)', '["sh", "-c", "for u in kim lee park guest; do userdel -r $u 2>/dev/null; done\\nrm -rf /data/lee /srv/team; mkdir -p /data\\nfor g in devs audit ops team kim lee park guest; do groupdel $g 2>/dev/null; done\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\ngroupadd devs; groupadd audit\\nuseradd -m -s /bin/bash kim\\nuseradd -m -d /data/lee -s /bin/bash lee\\nuseradd -m -s /bin/bash guest\\nusermod -aG devs kim; usermod -aG devs lee; usermod -aG audit lee\\necho \\"draft report\\" > /tmp/lab/report.txt\\necho \\"team notes\\" > /tmp/lab/team.txt; chown kim:devs /tmp/lab/team.txt; chmod 644 /tmp/lab/team.txt\\necho hello > /home/guest/note.txt\\ntrue"]', '["sh", "-c", "( runuser -u lee -- test -w /tmp/lab/team.txt ) && ( [ \\"$(stat -c %A /tmp/lab/team.txt)\\" = \\"-rw-rw-r--\\" ] ) && ( [ \\"$(stat -c %U:%G /tmp/lab/team.txt)\\" = kim:devs ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "lee 가 쓸 수 있다", "cmd": ["sh", "-c", "runuser -u lee -- test -w /tmp/lab/team.txt"]}, {"label": "권한이 -rw-rw-r-- 다 (others 는 읽기만)", "cmd": ["sh", "-c", "[ \\"$(stat -c %A /tmp/lab/team.txt)\\" = \\"-rw-rw-r--\\" ]"]}, {"label": "소유자와 그룹은 그대로다", "cmd": ["sh", "-c", "[ \\"$(stat -c %U:%G /tmp/lab/team.txt)\\" = kim:devs ]"]}]', '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 9, 'su 와 su - 의 차이', '`root` 로 접속한 상태에서 `su kim` 과 `su - kim` 은 같은 걸까요? 알맞은 설명을 고르세요.', '`man su` 에서 `-`, `-l`, `--login` 항목을 찾아보세요. 이름 뒤에 붙은 하이픈 하나의 의미입니다.', NULL, NULL, '[]', 'choice', '["`su - kim` 은 비밀번호를 묻지 않고, `su kim` 은 항상 묻는다", "`su - kim` 은 root 로 올라가는 명령이고, `su kim` 은 kim 권한만 가진다", "`su - kim` 은 kim 의 로그인 환경(홈 디렉터리, 환경변수, 로그인 셸 설정)으로 들어가고, `su kim` 은 현재 작업 디렉터리와 환경 대부분을 그대로 가져간다", "둘은 완전히 같고, 하이픈은 출력 메시지를 줄이는 옵션이다"]', 2, '`su - 사용자`(= `-l`)는 그 사용자가 직접 로그인한 것처럼 홈 디렉터리로 이동하고 환경변수와 셸 시작 파일을 새로 읽습니다. 하이픈이 없으면 현재 작업 디렉터리와 환경 대부분이 유지됩니다. 비밀번호를 묻는 규칙은 둘이 같고(root 가 실행하면 둘 다 묻지 않음), 두 명령 모두 대상은 지정한 `kim` 이며, 하이픈은 출력 양과 무관합니다.', NULL, NULL, NULL, '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 10, 'kim 의 권한으로 명령 실행하기 (su - 사용자 -c)', '`kim` 이 직접 만든 파일처럼 보이게 하려고 합니다. root 로 로그인한 채, **`kim` 의 권한으로** `id -un` 의 결과를 `/tmp/by_kim.txt` 에 저장하세요. (파일 안에는 `kim` 이 들어가고 파일 주인도 `kim` 이어야 합니다.)', '`su - 사용자 -c ''명령''` 은 그 사용자로 명령 하나만 실행합니다. 리다이렉션(`>`)까지 **따옴표 안에** 넣어야 파일도 그 사용자 소유로 만들어집니다. 따옴표 밖에 두면 root 가 파일을 만들어요. `runuser -u kim -- 명령` 도 같은 일을 합니다.', 'su - kim -c ''id -un > /tmp/by_kim.txt''
cat /tmp/by_kim.txt
ls -l /tmp/by_kim.txt

# su - kim -c id -un > 파일 처럼 따옴표 밖에 > 를 쓰면 root 의 셸이 파일을 만들어 소유자가 root 가 된다', '["sh", "-c", "for u in kim lee park guest; do userdel -r $u 2>/dev/null; done\\nrm -rf /data/lee /srv/team; mkdir -p /data\\nfor g in devs audit ops team kim lee park guest; do groupdel $g 2>/dev/null; done\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\ngroupadd devs; groupadd audit\\nuseradd -m -s /bin/bash kim\\nuseradd -m -d /data/lee -s /bin/bash lee\\nuseradd -m -s /bin/bash guest\\nusermod -aG devs kim; usermod -aG devs lee; usermod -aG audit lee\\necho \\"draft report\\" > /tmp/lab/report.txt\\necho \\"team notes\\" > /tmp/lab/team.txt; chown kim:devs /tmp/lab/team.txt; chmod 644 /tmp/lab/team.txt\\necho hello > /home/guest/note.txt\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/by_kim.txt)\\" = kim ] ) && ( [ \\"$(stat -c %U /tmp/by_kim.txt)\\" = kim ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "내용이 kim 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/by_kim.txt)\\" = kim ]"]}, {"label": "파일 소유자가 kim 이다", "cmd": ["sh", "-c", "[ \\"$(stat -c %U /tmp/by_kim.txt)\\" = kim ]"]}]', '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 11, '계정과 홈 디렉터리 함께 지우기 (userdel -r)', '`guest` 계정을 **홈 디렉터리(`/home/guest`)까지 함께** 삭제하세요. 다른 계정(`kim`, `lee`)은 건드리면 안 됩니다.', '`userdel 이름` 만 쓰면 계정은 지워져도 홈 디렉터리와 파일은 남습니다. 홈과 메일함까지 지우는 옵션을 `userdel --help` 에서 찾아보세요.', 'ls -ld /home/guest
userdel -r guest
ls -ld /home/guest
getent passwd guest

# -r 없이 지우면 /home/guest 가 남고, 그 파일은 UID 숫자만 남은 주인 없는 파일이 된다', '["sh", "-c", "for u in kim lee park guest; do userdel -r $u 2>/dev/null; done\\nrm -rf /data/lee /srv/team; mkdir -p /data\\nfor g in devs audit ops team kim lee park guest; do groupdel $g 2>/dev/null; done\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\ngroupadd devs; groupadd audit\\nuseradd -m -s /bin/bash kim\\nuseradd -m -d /data/lee -s /bin/bash lee\\nuseradd -m -s /bin/bash guest\\nusermod -aG devs kim; usermod -aG devs lee; usermod -aG audit lee\\necho \\"draft report\\" > /tmp/lab/report.txt\\necho \\"team notes\\" > /tmp/lab/team.txt; chown kim:devs /tmp/lab/team.txt; chmod 644 /tmp/lab/team.txt\\necho hello > /home/guest/note.txt\\ntrue"]', '["sh", "-c", "( ! getent passwd guest > /dev/null ) && ( [ ! -d /home/guest ] ) && ( getent passwd kim > /dev/null && getent passwd lee > /dev/null && [ -d /home/kim ] && [ -d /data/lee ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "guest 계정이 없다", "cmd": ["sh", "-c", "! getent passwd guest > /dev/null"]}, {"label": "홈 디렉터리가 없다", "cmd": ["sh", "-c", "[ ! -d /home/guest ]"]}, {"label": "kim 과 lee 는 그대로 있다", "cmd": ["sh", "-c", "getent passwd kim > /dev/null && getent passwd lee > /dev/null && [ -d /home/kim ] && [ -d /data/lee ]"]}]', '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]'),
  (232, 12, '새 팀원이 공유 폴더를 쓰게 만드는 순서', '`team` 그룹이 함께 쓰는 폴더 `/srv/team` 을 만들고, 신입 `newbie` 가 그 폴더에 파일을 만들 수 있게 해야 합니다. 알맞은 순서대로 놓으세요. **앞에서 뒤**로 놓습니다.', '그룹이 있어야 계정을 그 그룹에 넣을 수 있고, 폴더에 그룹을 지정해야 그룹 권한이 의미가 있습니다. 마지막에는 실제로 되는지 확인합니다.', NULL, NULL, '[]', 'order', '["`groupadd team` 으로 그룹을 만든다", "`useradd -m -G team newbie` 로 계정을 만들면서 그룹에 넣는다", "`mkdir /srv/team` 으로 공유 폴더를 만든다", "`chown :team /srv/team` 과 `chmod g+w /srv/team` 으로 폴더의 그룹과 그룹 쓰기 권한을 정한다", "`runuser -u newbie -- touch /srv/team/hello` 로 newbie 가 실제로 파일을 만들 수 있는지 확인한다"]', NULL, '**그룹 만들기 → 계정 만들며 그룹에 넣기 → 폴더 만들기 → 폴더 그룹·권한 정하기 → 계정으로 확인** 입니다. 그룹이 없으면 `useradd -G` 가 실패하고, 폴더의 그룹과 `g+w` 를 정하지 않으면 그룹에 들어가 있어도 쓸 수 없으며, 마지막 확인을 root 로 하면 권한과 상관없이 성공해 버리므로 반드시 해당 계정으로 확인합니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "passwd(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/passwd.5.html"}, {"title": "group(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/group.5.html"}, {"title": "useradd(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/useradd.8.html"}, {"title": "usermod(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/usermod.8.html"}]');
